using Microsoft.ApplicationInsights.Channel;
using Microsoft.ApplicationInsights.DataContracts;
using Microsoft.ApplicationInsights.Extensibility;

public class AiTelemetryInitializer : ITelemetryInitializer
{
    private readonly IHttpContextAccessor _httpContextAccessor;

    public AiTelemetryInitializer(IHttpContextAccessor httpContextAccessor)
    {
        _httpContextAccessor = httpContextAccessor;
    }

    public void Initialize(ITelemetry telemetry)
    {
        var httpContext = _httpContextAccessor.HttpContext;
        if (httpContext != null)
        {
            var tenantId = httpContext.User.FindFirst("tenant_id")?.Value ?? "anonymous";
            telemetry.Context.GlobalProperties["TenantId"] = tenantId;
        }

        // Tag with active model deployment details
        telemetry.Context.GlobalProperties["AiDeploymentRegion"] = "eastus";
        telemetry.Context.GlobalProperties["PrimaryModel"] = "gpt-4o";
    }
}

// In Program.cs: Register in DI
builder.Services.AddSingleton<ITelemetryInitializer, AiTelemetryInitializer>();
